parameters.jsonBody:
={
  "model": "qwen-audio-3.1-asr-flash",
  "input": {
    "messages": [
      {
        "role": "user",
        "content": [
          {
            "type": "text",
            "text": "You are a professional transcriber. You MUST transcribe the audio directly into pure Urdu (اردو) script. DO NOT output in Hindi or Devanagari script."
          },
          {
            "type": "input_audio",
            "input_audio": {
              "data": "{{ $json.base64_audio }}"
            }
          }
        ]
      }
    ]
  },
  "parameters": {
    "format": "wav",
    "sample_rate": "16000",
    "language": "ur"
  }
}

parameters.jsCode:
const item = $input.all()[0];
const binaryData = item.binary;

if (binaryData) {
    // Pehli file (audio) ka naam nikalna
    const fileKey = Object.keys(binaryData)[0];
    const fileObject = binaryData[fileKey];

    // Binary ko parhna aur Base64 mein badalna
    const fileBuffer = await this.helpers.getBinaryDataBuffer(0, fileKey);
    const base64Encoded = fileBuffer.toString('base64');
    const mimeType = fileObject.mimeType || 'audio/wav';

    // Qwen ke liye Data URI format banana
    const finalBase64Data = `data:${mimeType};base64,${base64Encoded}`;

    // Agle node ko bhejna
    return [{ json: { base64_audio: finalBase64Data } }];
} else {
    return [{ json: { base64_audio: '' } }];
}
